#include "gemm_config.h" // Should be generated by tune flow
#include <cassert>
extern "C"
{
    /**
     * @brief interface wrapper
     *
     */
    void dgemm_(char const *transA, char const *transB, int const *m,
        int const *n, int const *k, double const *alpha, double const *A,
        int const *lda, double const *B, int const *ldb, double const *beta,
        double *C, int const *ldc)
    {
        assert((*transA == 'N' || *transA == 'n')
            && (*transB == 'N' || *transB == 'n')
            && "loopmaster gencode currently\
            only support NN ");
        CurrentGemmType gemm_nn_func;
        gemm_nn_func(*m, *n, *k, *alpha, A, *lda, B, *ldb, *beta, C, *ldc);
    }
}